const input = $input.first().json;
const daysBetween = (a, b) => Math.floor((new Date(b) - new Date(a)) / 86400000);
const measure = (company_key, code, value, status, source, as_of_date, confidence, reason) => ({ measure_key: `${company_key}:${input.health_normalization_version}:${code}`, company_key, measure_code: code, value: value ?? null, status, source, as_of_date: as_of_date || null, confidence, reason, health_normalization_version: input.health_normalization_version, updated_at: input.now_utc });
const out = [];
for (const company of input.companies || []) {
  const key = company.company_key;
  const sirene = input.sirene_by_company_key[key] || {};
  const pappers = input.pappers_by_company_key[key] || null;
  const sireneState = sirene.administrative_status || company.administrative_status || null;
  const pappersInactive = pappers?.entreprise_cessee === true;
  let adminStatus = sireneState ? 'known' : 'unknown';
  let reason = sireneState ? 'G8N_HEALTH_SIRENE_ADMIN_STATE' : 'G8N_HEALTH_UNKNOWN_ADMIN_STATE';
  if ((sireneState === 'active' && pappersInactive) || (sireneState === 'inactive' && pappers?.entreprise_cessee === false)) { adminStatus = 'conflict'; reason = 'G8N_HEALTH_PROVIDER_CONFLICT'; }
  out.push(measure(key, 'administrative_state', sireneState || (pappersInactive ? 'inactive' : null), adminStatus, pappers ? 'sirene+pappers_optional' : 'sirene', sirene.as_of_date || pappers?.as_of_date || null, adminStatus === 'conflict' ? 0.55 : adminStatus === 'known' ? 0.9 : 0.35, reason));
  out.push(measure(key, 'employee_band', sirene.employee_band || pappers?.effectif || null, sirene.employee_band || pappers?.effectif ? 'known' : 'unknown', sirene.employee_band ? 'sirene' : pappers ? 'pappers_optional' : 'none', sirene.as_of_date || pappers?.as_of_date || null, sirene.employee_band || pappers?.effectif ? 0.75 : 0.3, 'G8N_HEALTH_EMPLOYEE_BAND'));
  const financialAsOf = pappers?.financial_as_of_date || null;
  const financialAge = financialAsOf ? daysBetween(financialAsOf, input.now_utc) : null;
  const financialStatus = !pappers ? 'unknown' : !financialAsOf ? 'unknown' : financialAge > 365 ? 'stale' : 'known';
  out.push(measure(key, 'financials_available', pappers?.revenue ?? null, financialStatus, pappers ? 'pappers_optional' : 'none', financialAsOf, financialStatus === 'known' ? 0.75 : financialStatus === 'stale' ? 0.45 : 0.25, financialStatus === 'unknown' ? 'G8N_HEALTH_FINANCIAL_UNKNOWN_NOT_ZERO' : 'G8N_HEALTH_FINANCIAL_AVAILABLE'));
  const risk = sireneState === 'inactive' || pappersInactive ? 'inactive_company' : pappers?.procedure_collective ? 'collective_procedure' : null;
  out.push(measure(key, 'risk_signal', risk, risk ? 'known' : 'unknown', risk ? (pappersInactive ? 'pappers_optional' : 'sirene') : 'none', pappers?.as_of_date || sirene.as_of_date || null, risk ? 0.85 : 0.3, risk ? 'G8N_HEALTH_EXPLICIT_RISK' : 'G8N_HEALTH_NO_EXPLICIT_RISK_AVAILABLE'));
}
return [{ json: { ...input, company_health_measure_upserts: out, next_step: 'Wire company_health_measures upsert locally. Unknown is not a penalty.' } }];
